//! `gen-rbac`: derive the operator's `ClusterRole` from the kube-rs
//! [`kube::Resource`] traits actually used and write it to `deploy/rbac/`.
//!
//! Every resource name and API group below is derived from a `Resource`
//! impl (`<K as Resource>::plural` / `::group`), so adding a new child kind
//! to a reconciler without extending [`covered_kinds`] breaks compilation
//! of the table, and the `--check` drift gate (plan todo 34) catches a
//! stale generated file. Verbs are the narrowest correct set per resource,
//! evidenced by the call sites named on each rule. No rule grants `*`.

use std::path::{Path, PathBuf};

use hydradb_operator_api::crd::{GraphCluster, GraphIndexer, GraphNodePool};
use k8s_openapi::api::apps::v1::{Deployment, StatefulSet};
use k8s_openapi::api::coordination::v1::Lease;
use k8s_openapi::api::core::v1::{ConfigMap, Event, PersistentVolumeClaim, Pod, Secret, Service};
use k8s_openapi::api::networking::v1::NetworkPolicy;
use k8s_openapi::api::policy::v1::PodDisruptionBudget;
use k8s_openapi::api::rbac::v1::{ClusterRole, PolicyRule};
use k8s_openapi::apimachinery::pkg::apis::meta::v1::ObjectMeta;
use kube::Resource as _;

/// Output file (relative to the workspace root) receiving the `ClusterRole`.
///
/// Chart templates (plan todo 37) source their RBAC from this directory.
const OUTPUT_FILE: &str = "deploy/rbac/operator-clusterrole.yaml";

/// Header carried by every generated file: generated marker plus the exact
/// regeneration command. Mirrors the no-hand-edit discipline of `gen-crds`.
const HEADER: &str = "# GENERATED by `cargo xtask gen-rbac` — do not hand-edit.\n# Regenerate with: cargo xtask gen-rbac\n";

/// Marker for the `ServiceMonitor` child kind (plan todo 22).
///
/// `monitoring.coreos.com` is not part of `k8s-openapi`, so there is no
/// upstream `Resource` impl to reuse; this marker pins the same contract
/// (group, version, kind, plural) the reconciler will consume.
struct ServiceMonitor {
    metadata: ObjectMeta,
}

impl kube::Resource for ServiceMonitor {
    type DynamicType = ();
    type Scope = kube::core::NamespaceResourceScope;

    fn meta(&self) -> &ObjectMeta {
        &self.metadata
    }

    fn meta_mut(&mut self) -> &mut ObjectMeta {
        &mut self.metadata
    }

    fn group(_: &()) -> std::borrow::Cow<'_, str> {
        std::borrow::Cow::Borrowed("monitoring.coreos.com")
    }

    fn version(_: &()) -> std::borrow::Cow<'_, str> {
        std::borrow::Cow::Borrowed("v1")
    }

    fn kind(_: &()) -> std::borrow::Cow<'_, str> {
        std::borrow::Cow::Borrowed("ServiceMonitor")
    }

    fn plural(_: &()) -> std::borrow::Cow<'_, str> {
        std::borrow::Cow::Borrowed("servicemonitors")
    }
}

/// Marker for the `ObjectBucketClaim` kind backing `spec.objectStore`.
///
/// `objectbucket.io` (Rook/Ceph) is not part of `k8s-openapi`. The
/// cluster reconciler (`reconcile/cluster.rs`) reads the OBC's generated
/// Secret and ConfigMap; the OBC itself is user-created, so verbs stay
/// read-only.
struct ObjectBucketClaim {
    metadata: ObjectMeta,
}

impl kube::Resource for ObjectBucketClaim {
    type DynamicType = ();
    type Scope = kube::core::NamespaceResourceScope;

    fn meta(&self) -> &ObjectMeta {
        &self.metadata
    }

    fn meta_mut(&mut self) -> &mut ObjectMeta {
        &mut self.metadata
    }

    fn group(_: &()) -> std::borrow::Cow<'_, str> {
        std::borrow::Cow::Borrowed("objectbucket.io")
    }

    fn version(_: &()) -> std::borrow::Cow<'_, str> {
        std::borrow::Cow::Borrowed("v1alpha1")
    }

    fn kind(_: &()) -> std::borrow::Cow<'_, str> {
        std::borrow::Cow::Borrowed("ObjectBucketClaim")
    }

    fn plural(_: &()) -> std::borrow::Cow<'_, str> {
        std::borrow::Cow::Borrowed("objectbucketclaims")
    }
}

/// One RBAC rule with its provenance: which source reality requires it.
struct Rule {
    api_group: String,
    resources: Vec<String>,
    verbs: Vec<String>,
}

/// Build one rule from `Resource` impls, deriving group and plural from the
/// traits rather than retyping them as string literals.
fn rule<K: kube::Resource<DynamicType = ()>>(
    resources: Vec<String>,
    verbs: &[&str],
) -> anyhow::Result<Rule> {
    let group = K::group(&()).into_owned();
    for resource in &resources {
        if resource.is_empty() || resource.contains('*') {
            anyhow::bail!("refusing to emit wildcard or empty resource");
        }
    }
    for verb in verbs {
        if *verb == "*" {
            anyhow::bail!("refusing to emit wildcard verb");
        }
    }
    Ok(Rule {
        api_group: group,
        resources,
        verbs: verbs.iter().map(|verb| (*verb).to_owned()).collect(),
    })
}

/// The full rule table in stable emission order.
///
/// Provenance per rule:
/// - CRDs: `Ctx` holds `Api::all` per kind (`context.rs`); controllers
///   watch them (`run.rs`); reconcilers `get` the live object and
///   `patch_status` (`reconcile/cluster.rs`, `nodepool.rs`, `indexer.rs`);
///   `finalizer.rs` Merge-patches the finalizer itself, hence `update` and
///   `patch` on the CRs. The operator never creates or deletes CRs.
/// - `/status`: `patch_status` in all three reconcilers; `patch` mandatory.
/// - StatefulSet/Deployment/ConfigMap/Secret/Service: `apply_child` SSA
///   `patch` (`apply.rs`) plus label-filtered `.owns()` watches (`run.rs`);
///   `create`/`update`/`delete` cover the full child lifecycle (SSA
///   create-or-patch plus garbage-collection-aware cleanup).
/// - Pod: the cluster reconciler `list`s live pods by label selector to
///   build the Bolt routing table (`reconcile/cluster.rs`); read-only.
/// - PersistentVolumeClaim: the nodepool reconciler embeds a single
///   `volumeClaimTemplates` entry (`reconcile/nodepool.rs`); the
///   controller never manages PVC objects directly, so read-only.
/// - Event: `Error::should_emit_event` (`error.rs`) marks human-actionable
///   failures for the Kubernetes event recorder; `create`/`patch` let the
///   recorder write, reads let it find the existing event.
/// - PodDisruptionBudget / NetworkPolicy / ServiceMonitor: declared
///   operator surface (plan todo 22) with no reconciler yet
///   (`reconcile/indexer.rs` carries the `TODO(todo-22)` marker). RBAC
///   must exist BEFORE its consumers, so they ship here with the full
///   child-lifecycle verbs.
/// - Lease: leader-election identity (`context.rs` documents the operator
///   namespace for leader-election); standard `coordination.k8s.io` set.
/// - ObjectBucketClaim: read-only (see marker docs above).
fn covered_kinds() -> anyhow::Result<Vec<Rule>> {
    let crd_group = GraphCluster::group(&()).into_owned();
    let crds = vec![
        GraphCluster::plural(&()).into_owned(),
        GraphNodePool::plural(&()).into_owned(),
        GraphIndexer::plural(&()).into_owned(),
    ];
    for plural in &crds {
        if plural.is_empty() {
            anyhow::bail!("CRD plural derived from Resource trait is empty");
        }
    }
    let status: Vec<String> = crds
        .iter()
        .map(|plural| format!("{plural}/status"))
        .collect();

    let full_lifecycle = [
        "get", "list", "watch", "create", "update", "patch", "delete",
    ];
    let read_only = ["get", "list", "watch"];

    Ok(vec![
        // The three CRDs themselves (finalizer path needs update+patch).
        Rule {
            api_group: crd_group.clone(),
            resources: crds,
            verbs: vec!["get", "list", "watch", "update", "patch"]
                .into_iter()
                .map(str::to_owned)
                .collect(),
        },
        // The three `/status` subresources (`patch` mandatory).
        Rule {
            api_group: crd_group,
            resources: status,
            verbs: vec!["get", "update", "patch"]
                .into_iter()
                .map(str::to_owned)
                .collect(),
        },
        rule::<StatefulSet>(vec![StatefulSet::plural(&()).into_owned()], &full_lifecycle)?,
        rule::<Deployment>(vec![Deployment::plural(&()).into_owned()], &full_lifecycle)?,
        rule::<Service>(vec![Service::plural(&()).into_owned()], &full_lifecycle)?,
        rule::<ConfigMap>(vec![ConfigMap::plural(&()).into_owned()], &full_lifecycle)?,
        rule::<Secret>(vec![Secret::plural(&()).into_owned()], &full_lifecycle)?,
        rule::<Pod>(vec![Pod::plural(&()).into_owned()], &read_only)?,
        rule::<PersistentVolumeClaim>(
            vec![PersistentVolumeClaim::plural(&()).into_owned()],
            &read_only,
        )?,
        rule::<Event>(
            vec![Event::plural(&()).into_owned()],
            &["get", "list", "watch", "create", "patch"],
        )?,
        rule::<PodDisruptionBudget>(
            vec![PodDisruptionBudget::plural(&()).into_owned()],
            &full_lifecycle,
        )?,
        rule::<NetworkPolicy>(
            vec![NetworkPolicy::plural(&()).into_owned()],
            &full_lifecycle,
        )?,
        rule::<ServiceMonitor>(
            vec![ServiceMonitor::plural(&()).into_owned()],
            &full_lifecycle,
        )?,
        rule::<Lease>(vec![Lease::plural(&()).into_owned()], &full_lifecycle)?,
        rule::<ObjectBucketClaim>(
            vec![ObjectBucketClaim::plural(&()).into_owned()],
            &read_only,
        )?,
    ])
}

/// Render the `ClusterRole` with a stable field order and exactly one
/// trailing newline, behind the generated-file header.
fn render(rules: &[Rule]) -> anyhow::Result<String> {
    let policy_rules: Vec<PolicyRule> = rules
        .iter()
        .map(|item| PolicyRule {
            api_groups: Some(vec![item.api_group.clone()]),
            resources: Some(item.resources.clone()),
            verbs: item.verbs.clone(),
            ..Default::default()
        })
        .collect();
    let role = ClusterRole {
        metadata: ObjectMeta {
            name: Some("hydradb-operator".to_owned()),
            labels: Some(
                [
                    ("app.kubernetes.io/name".to_owned(), "hydradb".to_owned()),
                    (
                        "app.kubernetes.io/managed-by".to_owned(),
                        "hydradb-operator".to_owned(),
                    ),
                    ("app.kubernetes.io/part-of".to_owned(), "hydradb".to_owned()),
                ]
                .into_iter()
                .collect(),
            ),
            ..Default::default()
        },
        rules: Some(policy_rules),
        ..Default::default()
    };
    let mut yaml = serde_saphyr::to_string(&role)?;
    if !yaml.ends_with('\n') {
        yaml.push('\n');
    }
    Ok(format!("{HEADER}---\n{yaml}"))
}

/// Workspace root derived from this crate's manifest location.
///
/// `CARGO_MANIFEST_DIR` is `crates/xtask` both for the binary and for
/// integration tests, so two ancestors up is the workspace root regardless
/// of the process working directory.
fn workspace_root() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR"))
        .ancestors()
        .nth(2)
        .map(Path::to_path_buf)
        .unwrap_or_else(|| PathBuf::from("."))
}

/// Write `contents` to `path` only when the bytes differ (keeps runs
/// idempotent without churning mtimes).
fn write_if_different(path: &Path, contents: &str) -> anyhow::Result<()> {
    let current = std::fs::read_to_string(path).unwrap_or_default();
    if current != contents {
        if let Some(parent) = path.parent() {
            std::fs::create_dir_all(parent)?;
        }
        std::fs::write(path, contents)?;
    }
    Ok(())
}

/// Render the operator `ClusterRole` without writing.
///
/// Returns the `(relative path, contents)` pair so the `--check` drift gate
/// can diff without writing.
pub fn render_all() -> anyhow::Result<Vec<(String, String)>> {
    let rules = covered_kinds()?;
    let yaml = render(&rules)?;
    Ok(vec![(OUTPUT_FILE.to_owned(), yaml)])
}

/// Generate the operator `ClusterRole` into `deploy/rbac/`.
pub fn run() -> anyhow::Result<()> {
    let root = workspace_root();
    for (rel, contents) in render_all()? {
        let path = root.join(&rel);
        write_if_different(&path, &contents)?;
        println!("wrote {rel}");
    }
    Ok(())
}
